/**
 * Unit tests for DefaultTypeResolverBuilder#useForType.
 */
public class DefaultTypeResolverBuilder_useForType_TriageGen1Test {

    public enum DefaultTyping {
        NON_CONCRETE_AND_ARRAYS,
        OBJECT_AND_NON_CONCRETE,
        NON_FINAL,
        JAVA_LANG_OBJECT // Used for default case logic
    }

    @Test
    public void testUseForType_NonConcreteAndArrays_ArrayToConcrete() {
        // Case: NON_CONCRETE_AND_ARRAYS -> Array -> Concrete (not Object/TreeNode)
        DefaultTypeResolverBuilder builder = new DefaultTypeResolverBuilder(DefaultTyping.NON_CONCRETE_AND_ARRAYS);
        JavaType arrayType = mock(JavaType.class);
        JavaType contentType = mock(JavaType.class);

        when(arrayType.isArrayType()).thenReturn(true);
        when(arrayType.getContentType()).thenReturn(contentType);
        when(contentType.isArrayType()).thenReturn(false);
        when(contentType.getRawClass()).thenReturn(String.class);
        when(contentType.isConcrete()).thenReturn(true);

        // Should fall through to OBJECT_AND_NON_CONCRETE logic
        // (String.class != Object.class) && !(true && !TreeNode) -> false
        assertFalse(builder.useForType(arrayType));
    }

    @Test
    public void testUseForType_NonConcreteAndArrays_ArrayToObject() {
        // Case: NON_CONCRETE_AND_ARRAYS -> Array -> Object
        DefaultTypeResolverBuilder builder = new DefaultTypeResolverBuilder(DefaultTyping.NON_CONCRETE_AND_ARRAYS);
        JavaType arrayType = mock(JavaType.class);
        JavaType contentType = mock(JavaType.class);

        when(arrayType.isArrayType()).thenReturn(true);
        when(arrayType.getContentType()).thenReturn(contentType);
        when(contentType.isArrayType()).thenReturn(false);
        when(contentType.getRawClass()).thenReturn(Object.class);

        assertTrue(builder.useForType(arrayType));
    }

    @Test
    public void testUseForType_ObjectAndNonConcrete_IsObject() {
        DefaultTypeResolverBuilder builder = new DefaultTypeResolverBuilder(DefaultTyping.OBJECT_AND_NON_CONCRETE);
        JavaType t = mock(JavaType.class);
        when(t.getRawClass()).thenReturn(Object.class);

        assertTrue(builder.useForType(t));
    }

    @Test
    public void testUseForType_ObjectAndNonConcrete_IsNonConcrete() {
        DefaultTypeResolverBuilder builder = new DefaultTypeResolverBuilder(DefaultTyping.OBJECT_AND_NON_CONCRETE);
        JavaType t = mock(JavaType.class);
        when(t.getRawClass()).thenReturn(String.class);
        when(t.isConcrete()).thenReturn(false);

        assertTrue(builder.useForType(t));
    }

    @Test
    public void testUseForType_ObjectAndNonConcrete_IsTreeNode() {
        DefaultTypeResolverBuilder builder = new DefaultTypeResolverBuilder(DefaultTyping.OBJECT_AND_NON_CONCRETE);
        JavaType t = mock(JavaType.class);
        // Mocking TreeNode behavior
        when(t.getRawClass()).thenReturn(com.fasterxml.jackson.databind.node.TreeNode.class);
        when(t.isConcrete()).thenReturn(true);

        // Since it is TreeNode, even if concrete, the expression is:
        // (Object.class == Object.class) || (!true || TreeNode.isAssignableFrom(TreeNode.class))
        // Wait, the logic is: (t.getRawClass() == Object.class) || (!t.isConcrete() || TreeNode.class.isAssignableFrom(t.getRawClass()))
        // If t is TreeNode, isConcrete is true, so: (false || (false || true)) -> true
        assertTrue(builder.useForType(t));
    }

    @Test
    public void testUseForType_ObjectAndNonConcrete_ConcreteNonTreeNode() {
        DefaultTypeResolverBuilder builder = new DefaultTypeResolverBuilder(DefaultTyping.OBJECT_AND_NON_CONCRETE);
        JavaType t = mock(JavaType.class);
        when(t.getRawClass()).thenReturn(String.class);
        when(t.isConcrete()).thenReturn(true);

        assertFalse(builder.useForType(t));
    }

    @Test
    public void testUseForType_NonFinal_NonFinalAndNotTreeNode() {
        DefaultTypeResolverBuilder builder = new DefaultTypeResolverBuilder(DefaultTyping.NON_FINAL);
        JavaType t = mock(JavaType.class);
        when(t.isArrayType()).thenReturn(false);
        when(t.isFinal()).thenReturn(false);
        when(t.getRawClass()).thenReturn(String.class);

        assertTrue(builder.useForType(t));
    }

    @Test
    public void testUseForType_NonFinal_IsFinal() {
        DefaultTypeResolverBuilder builder = new DefaultTypeResolverBuilder(DefaultTyping.NON_FINAL);
        JavaType t = mock(JavaType.class);
        when(t.isArrayType()).thenReturn(false);
        when(t.isFinal()).thenReturn(true);

        assertFalse(builder.useForType(t));
    }

    @Test
    public void testUseForType_NonFinal_IsTreeNode() {
        DefaultTypeResolverBuilder builder = new DefaultTypeResolverBuilder(DefaultTyping.NON_FINAL);
        JavaType t = mock(JavaType.class);
        when(t.isArrayType()).thenReturn(false);
        when(t.isFinal()).thenReturn(false);
        when(t.getRawClass()).thenReturn(com.fasterxml.jackson.databind.node.TreeNode.class);

        assertFalse(builder.useForType(t));
    }

    @Test
    public void testUseForType_NonFinal_ArrayToFinal() {
        DefaultTypeResolverBuilder builder = new DefaultTypeResolverBuilder(DefaultTyping.NON_FINAL);
        JavaType arrayType = mock(JavaType.class);
        JavaType contentType = mock(JavaType.class);

        when(arrayType.isArrayType()).thenReturn(true);
        when(arrayType.getContentType()).thenReturn(contentType);
        when(contentType.isArrayType()).thenReturn(false);
        when(contentType.isFinal()).thenReturn(true);

        assertFalse(builder.useForType(arrayType));
    }

    @Test
    public void testUseForType_Default_IsObject() {
        // Using a value that hits the default case (e.g., JAVA_LANG_OBJECT or something not explicitly handled)
        DefaultTypeResolverBuilder builder = new DefaultTypeResolverBuilder(DefaultTyping.JAVA_LANG_OBJECT);
        JavaType t = mock(JavaType.class);
        when(t.getRawClass()).thenReturn(Object.class);

        assertTrue(builder.useForType(t));
    }

    @Test
    public void testUseForType_Default_NotObject() {
        DefaultTypeResolverBuilder builder = new DefaultTypeResolverBuilder(DefaultTyping.JAVA_LANG_OBJECT);
        JavaType t = mock(JavaType.class);
        when(t.getRawClass()).thenReturn(String.class);

        assertFalse(builder.useForType(t));
    }
}
